import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Mac 和 Windows 的截图默认存成 PNG，那些 PNG 大得吓人。一张截图可能 5MB，同样图片存成 JPG 只有 500KB。</p>\n<p>PNG 转 JPG 是缩小截图、照片和图形最快的方法，前提是它们不需要透明背景。画质损失很小，体积省得很大。</p>\n<p>这篇指南讲清转换怎么工作、什么时候该用，以及让大多数人栽跟头的透明问题怎么处理。</p>\n<h2 id=\"what-is-png-to-jpg\">什么是 PNG 转 JPG？</h2>\n<p>PNG 转 JPG 是读取 PNG 文件、重写成 JPG。像素不变，存储从无损压缩变成有损压缩。</p>\n<p>转换会丢弃一些细节来缩小文件。画质设置合理时，损失看不见，体积省得却很惊人，常常是 80% 到 90%。</p>\n<p>代价是透明背景。JPG 存不了透明像素，透明区域必须填上实心颜色，也就是底色。</p>\n<p>截图、照片和没有透明的图形，这笔交易显然值得。带透明的标志，则需要多想一想。</p>\n<h2 id=\"why-screenshots-are-huge\">PNG 截图为什么这么大？</h2>\n<p>截图存成 PNG，是因为操作系统想要完美画质。屏幕上的每个像素都精确存储，包括噪点、渐变和抗锯齿文字。</p>\n<p>视网膜屏和高分辨率屏幕让情况更糟。双倍分辨率的截图有四倍像素，PNG 必须把每个都存下来。</p>\n<p>截图里的照片是最大的开销。桌面壁纸或浏览器窗口里的照片是细节丰富的图片，PNG 以完整体积无损存储它。</p>\n<p>JPG 处理这些高效得多。它简化纹理和渐变，人眼几乎注意不到，文件缩小到十分之一。</p>\n<h2 id=\"quality-settings\">真正管用的画质设置</h2>\n<p>画质滑块范围 20% 到 100%。带文字的截图用 85% 到 90%，字母保持清晰，文件依然大幅缩小。</p>\n<p>存成 PNG 的照片用 80% 到 85% 是最佳区间。照片看起来干净，文件比 PNG 小得多。</p>\n<p>低于 70%，文字开始遭殃。小字母出现光晕，细线变模糊，截图必须保持可读时，别用低设置。</p>\n<p>图片要交给有大小限制的表格时，逐步降低画质。每步后检查大小，刚好符合就停。</p>\n<h2 id=\"matte-colour\">底色：填充透明区域</h2>\n<p>PNG 有透明区域时，转换器在写 JPG 之前必须用实心颜色填满它们。这个颜色就是底色，由你来选。</p>\n<p>白色是默认，也是最安全的选择。大多数文档、网页、表格都是白底，白底填充的标志放在那里很自然。</p>\n<p>深色设计用黑色，特定网站用品牌色。转换器支持任意十六进制颜色，能和页面精确匹配。</p>\n<p>下载前检查结果。底色错了的标志看起来像坏了，周围有个显眼的框，改个颜色只要十秒钟。</p>\n<h2 id=\"screenshots-and-text\">截图与文字锐利度</h2>\n<p>截图是 PNG 转 JPG 最好的使用场景。体积省得巨大，85% 画质以上文字依然可读。</p>\n<p>转换后检查小字。用“对比”查看器放大菜单、按钮、正文，确认没有模糊到认不出来。</p>\n<p>截图里的每个字母都必须完美时，比如法律证据或技术文档，考虑用 WebP。它在小尺寸下比 JPG 更能保留文字。</p>\n<p>聊天或邮件里分享的日常截图，85% 的 JPG 绰绰有余，文件更小、发送更快。</p>\n<h2 id=\"product-photos-and-logos\">产品图、抠图与标志</h2>\n<p>透明背景的产品照片在网店里很常见。转成 JPG 加白底后，就能交给要求 JPG 的平台了。</p>\n<p>白底是产品上架的标准。亚马逊、eBay 和大多数店铺都要求白底产品照，转换正好符合它们的规则。</p>\n<p>标志需要更小心。透明标志转 JPG 加白底，放在白页上很好看，放在彩色页上就错了。底色要匹配目的地。</p>\n<p>标志必须在很多背景上通用时，别转 JPG。留着 PNG 或 WebP，透明才能保留下来。</p>\n<h2 id=\"batch-converting-screenshots\">批量转换截图</h2>\n<p>一次能转换整批 25 张视网膜截图。每张独立转换，ZIP 里装着全部结果。</p>\n<p>每张文件最大接受 25MB，再大的视网膜截图也不用任何准备。</p>\n<p>整批用同样的画质和底色设置。截图属于同一文档或演示时，一致性很重要。</p>\n<p>转换后检查批量汇总。它把所有文件的节省加起来，好的批量常常能省 80% 以上。</p>\n<h2 id=\"file-size-savings\">能省多少体积？</h2>\n<p>一张典型的 5MB PNG 截图，85% 画质下变成 400KB 到 800KB 的 JPG。省了 85%，图片看起来依然干净。</p>\n<p>存成 PNG 的细节照片可能从 12MB 降到 1.5MB。按比例省得少一些，按绝对字节算依然惊人。</p>\n<p>简单图形省得最少。颜色少的扁平图标，PNG 本来就压得很好，只能省一半左右。</p>\n<p>极小的单色图标甚至可能变大。一张 20KB 的扁平图标转成 88% 的 JPG，可能多出几 KB，因为 JPG 增加了 PNG 不需要的额外开销。</p>\n<h2 id=\"png-vs-webp-decision\">PNG 转 JPG，还是 PNG 转 WebP？</h2>\n<p>目的地要求时选 JPG。表格、老软件、打印店常常明确列出 JPG，WebP 会被拒收。</p>\n<p>目的地是网站时选 WebP。WebP 保留透明、更好地保留文字，同等画质下文件比 JPG 更小。</p>\n<p>图片没有透明、必须处处能用时选 JPG。它是通用格式，过去三十年里做的系统没有一个会拒收它。</p>\n<p>截图要上网时，WebP 通常是更好的选择。截图要交给表格或邮件时，JPG 更稳妥。</p>\n<h2 id=\"metadata-stripped\">转换中清除的元数据</h2>\n<p>PNG 转 JPG 会清除嵌入的 PNG 文本块，比如创建软件备注和注释。画布重绘像素，元数据留不下来。</p>\n<p>这对隐私是好事。分享出去的 JPG 截图不记录创建它的软件或机器。</p>\n<p>存档工作却值得留意。PNG 文本块里有重要备注时，转换前先复制下来，JPG 不会携带它们。</p>\n<p>EXIF 数据也会清除，不过 PNG 本来就很少像 JPG 那样携带 EXIF。不管怎样，转好的文件都没有隐藏细节。</p>\n<h2 id=\"checking-quality\">下载前检查画质</h2>\n<p>用“对比”查看器检查转好的 JPG 和原 PNG。拖动分割线，看边缘和文字。</p>\n<p>窗口截图周围的柔和阴影值得仔细看。转换中阴影会变平，画质设置低时，柔和阴影可能变成一块一块的斑点。</p>\n<p>文件大小也要检查。JPG 只比 PNG 小一点，说明画质设得太高，或者图片是 PNG 本来就处理得很好的简单图形。</p>\n<p>结果发软时，把画质调高五点再转一次。原 PNG 还留在队列里，不用重新上传。</p>\n<h2 id=\"common-mistakes\">最容易犯的几个错误</h2>\n<p>最常见的错误是透明标志转 JPG 时没设底色。默认白色对深色页面可能是错的，标志最后陷在白框里。</p>\n<p>另一个错误是截图画质用得太低。文字最先遭殃，字母必须保持可读时，画质保持在 85% 或更高。</p>\n<p>还有人转换本来就很小的 PNG。一张 30KB 的图标不需要转换，转出来的 JPG 可能反而更大。</p>\n<p>最后，别把 PNG 转 JPG、再转回 PNG，还指望省空间。来回一趟叠加了 JPG 损伤，产出的 PNG 比原文件还大。</p>\n<h2 id=\"png-photos-from-phones\">手机里的 PNG 照片</h2>\n<p>有些手机会把照片存成 PNG，要么是设置、要么是应用的选择。那些照片比 JPG 照片大得多，转换能省下实实在在的存储空间。</p>\n<p>存成 PNG 的手机照片可能 10MB 以上，同样照片存成 JPG 只有 2MB。手机屏幕上看不出差别，省下的存储却很惊人。</p>\n<p>分享用的手机 PNG 照片，转 85% 画质的 JPG。照片看起来一样，文件发送更快，收件人哪里都能打开。</p>\n<p>打算编辑的照片，留一份 PNG 副本做原稿。无损格式经得起反复编辑，JPG 每次保存都会多一点损伤。</p>\n<p>手机总产出 PNG 时，检查相机设置。把相机换成 JPG，存储自动就省下来了，根本不用转换这一步。</p>\n<h2 id=\"screenshots-bug-reports\">缺陷报告用的截图</h2>\n<p>缺陷报告需要一张清楚显示问题的截图。PNG 截图是完美的证据，JPG 截图可能糊掉恰恰证明缺陷的那个细节。</p>\n<p>截图用完整分辨率拍，缺陷跟踪系统限制文件大小时，转 90% 画质的 JPG。文字保持可读，文件上传也没问题。</p>\n<p>转换前先给截图加标注，圈出问题区域。加在 PNG 版本上的标注保持清晰，同样标注加在 JPG 上，每保存一次就软一点。</p>\n<p>截图旁边附上重现缺陷的步骤。清楚的图片加清楚的步骤，比两者单独出现更能帮助开发者快速修复问题。</p>\n<p>转换后留着原 PNG 截图。开发者要求更清晰的版本时，PNG 已经准备好了，不用重新制造缺陷。</p>\n<h2 id=\"sharing-screenshots-chats\">聊天里分享截图</h2>\n<p>聊天里分享的截图常常是 PNG，网速弱时到得很慢。先转成 JPG，发送更快、每个人加载也更快。</p>\n<p>快速分享时，把截图粘贴进转换器，几秒就能下载 JPG。聊天群在用慢速移动数据时，这一步很值得。</p>\n<p>聊天截图的画质保持在 85%。文字保持可读，文件只有 PNG 的零头，消息马上就能发出。</p>\n<p>截图必须像素级完美时，比如付款确认，改发 PNG。文件大一点值得，因为每个数字都必须清晰可辨。</p>\n<p>聊天应用反正会压缩图片，JPG 输入比 PNG 输入结果更好。应用的压缩工作量更小，最终图片看起来更干净。</p>\n<h2 id=\"converting-for-email\">邮件用的图片转换</h2>\n<p>邮件附件有大小限制，通常 20MB 到 25MB，PNG 截图很快就会超。先转成 JPG，邮件就能控制在限制内。</p>\n<p>单张截图转 85% 画质的 JPG 再附上。文件只有 PNG 的零头，收件人看到的图片是一样的。</p>\n<p>好几张截图时，批量转换、一起附上 JPG。五张 PNG 截图可能是 25MB，JPG 版本总共才 4MB。</p>\n<p>图片特别多时，转好后把 JPG 打成一个压缩包。一个附件比十个好管理，收件人一次下载全部内容。</p>\n<p>发送前检查总大小。看一眼附件大小，能避免你以为邮件发出去了、结果收到退信的挫败。</p>\n<h2 id=\"archiving-converted-jpgs\">存档转好的 JPG</h2>\n<p>转好的 JPG 也值得像其他档案一样对待。按日期和用途分文件夹存放，两年前的文字以后还找得到。</p>\n<p>原 PNG 放在单独的存档文件夹里。它们是原稿，清楚的分隔能防止两套文件混在一起。</p>\n<p>转换后的文件按用途命名，而不是按日期。bug-report-login-error.jpg 这样的名字几年后还有用，screenshot-2026-11-17.jpg 这样的名字就没有。</p>\n<p>档案在两个地方备份。本地硬盘加云端备份，能防硬件故障、失窃和误删。</p>\n<p>每过一两年检查一次档案。不再重要的旧截图和照片可以删掉，给真正重要的文件腾出空间。</p>\n<p>准备好缩小截图了吗？打开<a href=\"/zh/png-zhuan-jpg/\">PNG 转 JPG 工具</a>，把它们拖进去。分步操作请读<a href=\"/zh/blog/ruhe-ba-png-zhuancheng-jpg/\">如何把 PNG 转换成 JPG</a>，体积取舍请看<a href=\"/zh/blog/png-zhuan-jpg-wenjian-daxiao-yu-huazhi/\">PNG 转 JPG：体积节省与画质取舍</a>。目的地是网站时，<a href=\"/zh/png-zhuan-webp/\">PNG 转 WebP 工具</a>可能更适合你。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"PNG 转 JPG 能小多少？","answer":"大多数截图能缩小 80% 到 90%，比如 85% 画质下从 5MB 变成 500KB。细节照片按比例省得少一些，但依然大幅缩小。简单图标几乎省不了，极小的单色图标甚至可能变大一点。"},{"question":"PNG 转 JPG 会糊掉截图里的文字吗？","answer":"低画质时会轻微糊掉，85% 或更高时不会。小字最先受 JPG 压缩影响，所以必须保持可读的截图要保持高画质。下载前用“对比”查看器放大文字检查。"},{"question":"透明标志用什么底色好？","answer":"匹配标志会出现位置的背景。白色适合大多数文档和网页，黑色适合深色设计，品牌十六进制颜色能精确匹配特定网站。使用前，先在目标背景上检查转好的标志。"},{"question":"手机上能把 PNG 转成 JPG 吗？","answer":"可以。在手机浏览器里打开工具，从相册里选 PNG 截图，下载 JPG 就行。转换在手机上运行，文件下载到设备里。手机上的批量保持适中，大 PNG 在移动端编码很花时间。"},{"question":"PNG 转 JPG 适合扫描件吗？","answer":"适合，而且是缩小大扫描件、方便发邮件的好办法。存成 PNG 的扫描页可能好几 MB，JPG 版本只有它的零头。画质保持在 85% 或更高，文字依然可读。"},{"question":"该把所有 PNG 文件都转成 JPG 省空间吗？","answer":"不该。截图、照片和没有透明的图形转就好，需要透明的标志、图标和图片留着 PNG 或 WebP。所有东西都转 JPG 会毁掉透明，还可能让简单图形更大，而不是更小。"}];
